from PIL import Image
img = Image.open('/app/output/final_poster.png')
pixels = img.load()
# Search for dark text pixels in the hero area (y 650-900, x 1400-2100)
for y in range(650, 900, 5):
    row = []
    for x in range(1500, 2000, 10):
        p = pixels[x, y]
        if p[0] < 50:
            row.append('X')
        else:
            row.append('.')
    if 'X' in row:
        print(f'y={y}: ' + ''.join(row))
"

python3 -c "
from PIL import Image
img = Image.open('/app/output/final_poster.png')
pixels = img.load()
# Check chart area for red line pixels
for y in range(1800, 2200, 20):
    row = []
    for x in range(200, 3300, 50):
        p = pixels[x, y]
        if p[0] > 200 and p[1] < 100 and p[2] < 100:
            row.append('R')
        elif p[0] > 40 and p[0] < 80:
            row.append('d')
        else:
            row.append('.')
    if 'R' in row or 'd' in row:
        print(f'y={y}: ' + ''.join(row))
"

